"""configloader — parse .ini-style config text into typed nested dicts."""


def _coerce(value):
    if value.startswith('"') and value.endswith('"') and len(value) >= 2:
        return value[1:-1]
    lowered = value.lower()
    if lowered == "true":
        return True
    if lowered == "false":
        return False
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value


def parse_config(text):
    config = {}
    section = ""
    config[section] = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            config.setdefault(section, {})
            continue
        key, _, value = line.partition("=")
        config[section][key.strip()] = _coerce(value.strip())
    return config


def get(config, dotted, default=None):
    section, _, key = dotted.partition(".")
    if not key:
        section, key = "", section
    return config.get(section, {}).get(key, default)

